package com.bank.hr;

import java.util.*;
import java.util.logging.*;

public class HrLookupDemo {
    private static final Logger log = Logger.getLogger("HrLookup");
    static {
        ConsoleHandler h = new ConsoleHandler();
        h.setFormatter(new SimpleFormatter());
        log.setUseParentHandlers(false);
        log.addHandler(h);
    }

    public static void main(String[] args) {
        List<Employee> withHr = List.of(
            new Employee(1L, "Rajesh", "IT"),
            new Employee(2L, "Priya", "HR"),
            new Employee(3L, "Amit", "Finance")
        );
        List<Employee> noHr = List.of(
            new Employee(1L, "Rajesh", "IT"),
            new Employee(3L, "Amit", "Finance")
        );
        HrLookupService service = new HrLookupService();

        // present case
        log.info(() -> "orElse (has HR): " + service.hrOrPlaceholder(withHr).getName());
        // empty cases
        log.info(() -> "orElse (no HR): " + service.hrOrPlaceholder(noHr).getName());
        log.info(() -> "orElseGet (no HR): " + service.hrOrLazyDefault(noHr).getName());
        try {
            service.hrOrThrow(noHr);
        } catch (NoSuchElementException ex) {
            log.warning("orElseThrow (no HR): " + ex.getMessage());
        }
    }
}

// ─── Would be in model/Employee.java ───
class Employee {
    private final Long id;
    private final String name;
    private final String department;
    Employee(Long id, String name, String department) { this.id = id; this.name = name; this.department = department; }
    String getName() { return name; }
    String getDepartment() { return department; }
}

// ─── Would be in service/HrLookupService.java ───
class HrLookupService {
    Optional<Employee> findAnyHr(List<Employee> employees) {
        return employees.stream()
            .filter(e -> "HR".equals(e.getDepartment()))
            .findAny();
    }

    // orElse: constant placeholder — fine because it is cheap and always-constructed is acceptable.
    Employee hrOrPlaceholder(List<Employee> employees) {
        return findAnyHr(employees).orElse(new Employee(0L, "<no HR staff>", "HR"));
    }

    // orElseGet: supplier runs ONLY when empty — use for an expensive/lazy fallback.
    Employee hrOrLazyDefault(List<Employee> employees) {
        return findAnyHr(employees).orElseGet(() -> {
            // imagine this is an expensive directory lookup; only runs if no HR found
            return new Employee(0L, "<fetched default HR>", "HR");
        });
    }

    // orElseThrow: fail fast for a strict workflow.
    Employee hrOrThrow(List<Employee> employees) {
        return findAnyHr(employees)
            .orElseThrow(() -> new NoSuchElementException("No HR employee available"));
    }
}
